'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dgeequb = require( './../lib/dgeequb.js' );


// FIXTURES //

var COLUMN_MAJOR = require( './fixtures/column_major.json' );
var ROW_MAJOR = require( './fixtures/row_major.json' );
var COLUMN_MAJOR_NONSQUARE = require( './fixtures/column_major_nonsquare.json' );
var ROW_MAJOR_NONSQUARE = require( './fixtures/row_major_nonsquare.json' );
var COLUMN_MAJOR_ZERO_ROW = require( './fixtures/column_major_zero_row.json' );
var ROW_MAJOR_ZERO_ROW = require( './fixtures/row_major_zero_row.json' );
var COLUMN_MAJOR_ZERO_COLUMN = require( './fixtures/column_major_zero_column.json' );
var ROW_MAJOR_ZERO_COLUMN = require( './fixtures/row_major_zero_column.json' );


// FUNCTIONS //

/**
* Asserts that a strided output vector matches a list of expected values, skipping expected values which are `null` (i.e., undefined upon early return).
*
* @private
* @param {Object} t - test object
* @param {Collection} actual - output array
* @param {Array} expected - expected values
* @param {integer} stride - index increment
* @param {NonNegativeInteger} offset - starting index
* @param {string} msg - assertion message prefix
*/
function isEqual( t, actual, expected, stride, offset, msg ) {
	var i;
	for ( i = 0; i < expected.length; i++ ) {
		if ( expected[ i ] === null ) {
			continue;
		}
		t.strictEqual( actual[ offset + ( i*stride ) ], expected[ i ], msg + '[' + i + ']' );
	}
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dgeequb, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 8', function test( t ) {
	t.strictEqual( dgeequb.length, 8, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided an invalid first argument', function test( t ) {
	var values;
	var i;

	values = [
		'foo',
		'bar',
		'',
		1,
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var out = new Float64Array( 3 );
			var R = new Float64Array( 2 );
			var C = new Float64Array( 2 );
			var A = new Float64Array( 4 );
			dgeequb( value, 2, 2, A, 2, R, C, out );
		};
	}
});

tape( 'the function throws an error if provided an invalid fifth argument (column-major)', function test( t ) {
	var values;
	var i;

	values = [
		-1,
		0,
		1
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var out = new Float64Array( 3 );
			var R = new Float64Array( 2 );
			var C = new Float64Array( 2 );
			var A = new Float64Array( 4 );
			dgeequb( 'column-major', 2, 2, A, value, R, C, out );
		};
	}
});

