tape( 'the function computes row and column scale factors (column-major)', function test( t ) {
	var data;
	var info;
	var out;
	var A;
	var R;
	var C;

	data = COLUMN_MAJOR;

	A = new Float64Array( data.A );
	R = new Float64Array( data.M );
	C = new Float64Array( data.N );
	out = new Float64Array( 3 );

	info = dgeequb( data.order, data.M, data.N, A, data.LDA, R, C, out );
	t.strictEqual( info, data.info, 'returns expected value' );
	isEqual( t, R, data.expected_R, 1, 0, 'R' );
	isEqual( t, C, data.expected_C, 1, 0, 'C' );
	isEqual( t, out, data.expected_out, 1, 0, 'out' );
	t.end();
});

